const keys = ['Core Activation','Core Design','Mobile Terminology','Mobile Design','Mobile Integration','Testing Layer','Testing Offshore','Carrier','Barrier'].map(k=>k.toLowerCase());
const out = [];
for (let r=2;r<=71;r++){ const t = wb.getRange('Sheet1!D'+r).getCell().getText().toLowerCase(); out.push([keys.some(k=>t.includes(k)) ? 'Billing PO' : null]); }
wb.getRange('Sheet1!F2:F71').setValues(out);
const hits=[], blanks=[];
for (let r=2;r<=71;r++){ const c=wb.getRange('Sheet1!F'+r).getCell(); const t=c.getText(); (t?hits:blanks).push(r+(t&&t!=="'Billing PO"?':'+t:'')); }
log('hits',hits.length,hits.join(','));
log('blanks',blanks.length,blanks.join(','));
